/**
 * @file robotic_sensor.h
 * @brief Compiled zero-allocation Port-Hamiltonian model generated by RT-MPBC.
 * Standard: MISRA-C:2012 / C99 bare-metal compatible.
 */

#ifndef RTMPBC_COMPILED_ROBOTIC_SENSOR_H
#define RTMPBC_COMPILED_ROBOTIC_SENSOR_H

#include "rtmpbc.h"

#define ROBOTIC_SENSOR_N_STATES 3
#define ROBOTIC_SENSOR_N_INPUTS 1
#define ROBOTIC_SENSOR_INPUTS_DIM 1
#define ROBOTIC_SENSOR_DT 0.0000500000

/* State variable indexing */
#define ROBOTIC_SENSOR_STATE_I_WINDING_INDUCTANCE 0
#define ROBOTIC_SENSOR_STATE_C_GEAR_FLEXSPLINE 1
#define ROBOTIC_SENSOR_STATE_I_LINK_PAYLOAD 2

/* Input port indexing */
#define ROBOTIC_SENSOR_INPUT_V_PWM_INVERTER 0

typedef struct {
    rtmpbc_real_t x[ROBOTIC_SENSOR_N_STATES];
    rtmpbc_real_t u[ROBOTIC_SENSOR_INPUTS_DIM];
    rtmpbc_real_t y[ROBOTIC_SENSOR_INPUTS_DIM];
    rtmpbc_real_t total_energy;
} robotic_sensor_sim_t;

void robotic_sensor_init(robotic_sensor_sim_t* sim);
void robotic_sensor_step(robotic_sensor_sim_t* sim);
rtmpbc_real_t robotic_sensor_energy(const robotic_sensor_sim_t* sim);

#endif /* RTMPBC_COMPILED_ROBOTIC_SENSOR_H */
